				draw();
			}

		},
		dispose() {

			if ( media ) {
				media.onload = media.onloadeddata = media.onerror = null;
				media.pause?.();
				media.removeAttribute( 'src' );
				media.load?.();
			}
			light.removeFromParent();
			texture.dispose();
			light.dispose();
			delete root.projectorFrame;

		}
	};

